const inp = $input.first().json;

// Todo viene de G54 - cero Airtable
const g54Data = inp.datosRecolectados || {};
const leadId  = inp.leadId  || null;
const estado  = inp.estado  || 'Nuevo';

const msgData        = { telefono: inp.telefono, texto: inp.texto || '', nombreContacto: inp.nombreContacto || '' };
const kbContexto     = inp.kbContexto || '';
const waConfig       = inp.waConfig || {};
const productosRaw   = inp.productos || [];

// emailVendedor ya viene calculado desde SW02
const emailVendedor = inp.emailVendedor || 'risosadmi@gmail.com';
const followup24    = inp.followup24 || waConfig.WA_FollowUp_24h || '';
const followup72    = inp.followup72 || waConfig.WA_FollowUp_72h || '';

// Datos recolectados: 100% desde G54 (ya enriquecidos por workaround en SW02)
let datosRecolectados = {
  producto:          g54Data.producto          || null,
  medidas:           g54Data.medidas           || null,
  fecha:             g54Data.fecha             || null,
  tipo_cajon:        g54Data.tipo_cajon        || null,
  proteccion_extra:  g54Data.proteccion_extra  ?? null,
  correo_contacto:   g54Data.correo_contacto   || null,
  nombre_cliente:    g54Data.nombre_cliente    || null,
  tipo_flujo:        g54Data.tipo_flujo        || null,
  cantidad:          g54Data.cantidad          || null,
  temaConsulta:      g54Data.temaConsulta      || null,
};

const cotizacionEnviada  = g54Data.cotizacion_enviada  || false;
const escaladaEnviada    = g54Data.escalada_enviada    || false;
const escaladaPendiente  = g54Data.escalada_pendiente  || false;
const idiomaGuardado     = g54Data.idioma              || null;

const historialRaw = inp.historial || '';
const historial    = historialRaw ? historialRaw.split('\n').slice(-20).join('\n') : '';
const esNuevo      = !leadId;
const texto        = msgData.texto;

// Catálogo ya viene calculado desde SW02
const catalogoProductos = inp.catalogoProductos || productosRaw.map(p => {
  const nombre = p.name || '';
  const desc = p.description || '';
  return nombre ? `${nombre}: ${desc}` : '';
}).filter(l => l.length > 2).join('\n');

// Detección de idioma
const isEN = (s) => /\b(hello|hi|good|morning|afternoon|evening|i|need|want|crate|box|ship|send|quote|price|size|wood|close|open)\b/i.test(s);
let idiomaConversacion = idiomaGuardado;
if (!idiomaConversacion) {
  idiomaConversacion = isEN(texto) ? 'inglés' : 'español';
}
const isEnglish = idiomaConversacion === 'inglés';

// Saludo según hora Miami
const h = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = isEnglish
  ? (h < 12 ? 'Good morning' : h < 19 ? 'Good afternoon' : 'Good evening')
  : (h < 12 ? 'Buenos días'  : h < 19 ? 'Buenas tardes'  : 'Buenas noches');

// Siguiente paso
const cleanVal = v => {
  if (typeof v === 'boolean') return v !== null ? v : null;
  if (!v || ['null','undefined','desconocido'].includes(String(v).trim().toLowerCase())) return null;
  return v;
};

const tieneProducto      = !!cleanVal(datosRecolectados.producto);
const tieneMedidas       = !!cleanVal(datosRecolectados.medidas);
const tieneFecha         = !!cleanVal(datosRecolectados.fecha);
const tieneTipoCajon     = !!cleanVal(datosRecolectados.tipo_cajon);
const tieneProteccion    = datosRecolectados.proteccion_extra !== null && datosRecolectados.proteccion_extra !== undefined;
const tieneCorreo        = !!cleanVal(datosRecolectados.correo_contacto);
const tieneNombre        = !!cleanVal(datosRecolectados.nombre_cliente);
const esCotizacion       = datosRecolectados.tipo_flujo === 'cotizacion';
const esConsulta         = datosRecolectados.tipo_flujo === 'consulta';

// Detecta si el mensaje ACTUAL contradice el tipo_flujo ya guardado (cambio de intención a mitad de conversación)
const regexSoloConsulta  = /\b(solo|s[oó]lo)\s+(quiero|necesito|busco)\s+(informaci[oó]n|saber|consultar)|es\s+(solo\s+|)una\s+consulta|quiero\s+(hacer\s+una\s+consulta|preguntar|consultar)|no\s+quiero\s+(una\s+|)cotizaci[oó]n|solo\s+(quiero\s+|)saber\s+(qu[eé]|los|las)|lo\s+que\s+(quiero|busco|necesito)\s+es\s+(informaci[oó]n|saber)|sin\s+compromiso/i;
const regexQuiereCotizar = /\b(quiero|necesito)\s+(una\s+|)cotizaci[oó]n|cu[aá]nto\s+(cuesta|sale|vale|cobran)|quiero\s+cotizar|dame\s+(un\s+|)precio/i;
const intentActualEnMensaje = regexSoloConsulta.test(texto) ? 'consulta' : (regexQuiereCotizar.test(texto) ? 'cotizacion' : null);
const cambioDeIntent = !!(intentActualEnMensaje && datosRecolectados.tipo_flujo && intentActualEnMensaje !== datosRecolectados.tipo_flujo);

let proximoPaso;
let instruccionPaso;

// Override: detectar intent post-venta ANTES de la máquina de estados
const esConsultaEstado = (
  // Cualquier pregunta por estado/seguimiento del pedido
  /estado|seguimiento|c[oó]mo va|c[oó]mo est[aá]|avance|proceso|en qu[eé] (va|est[aá]|quedo)/i.test(texto) ||
  // Ya hizo el pedido (con typos comunes)
  /ya (hice?|realic[eé]?|mand[eé]|envi[eé]|ped[ií]|coloqué|puse|lo ped[ií]|hiz)/i.test(texto) ||
  /hice? el pedido|realic[eé]? el pedido|ya ped[ií]|lo ped[ií]|ped[ií] por correo/i.test(texto) ||
  // Rechazo explícito del flujo comercial
  /no (quiero|necesito|me interesa) (otro|el|un|ning[uú]n)? ?(caj[oó]n|cajones|embalaje|caja|producto|recomend)/i.test(texto) ||
  // Ya tiene pedido
  /ya (tengo|realic[eé]?|hice?) (el |un |mi )?(pedido|orden|compra)/i.test(texto)
);

if (!tieneNombre) {
  proximoPaso = 'PRIMER_CONTACTO';
  if (historial.trim().length > 0) {
    // Historial existe: ya nos presentamos. El mensaje actual puede contener el nombre.
    instruccionPaso = isEnglish
      ? 'Extract the name from the current message (ignore prepositions: "with", "from", "and"). Greet them by name in datos_actualizados.nombre_cliente. If the historial already shows what they need (quote, product), confirm it and proceed — do NOT ask again.'
      : 'Extrae el nombre del mensaje actual (IGNORA preposiciones: "con"="with", "de", "y" — el nombre es el SUSTANTIVO PROPIO. "con Sol" → nombre es "Sol"). Salúdalo por nombre en datos_actualizados.nombre_cliente. Si en el historial ya expresaron qué necesitan (cotización, producto), confírmalo y avanza — NO vuelvas a preguntar.';
  } else {
    // Primer mensaje: presentarse obligatoriamente
    instruccionPaso = isEnglish
      ? 'MANDATORY: Start with "Hi! I\'m Marco, from Crating Express." Then acknowledge what the client said and ask for their name.'
      : 'OBLIGATORIO: Empieza con "Hola, soy Marco, asesor de Crating Express." Luego reconoce brevemente lo que dijeron y pide su nombre.';
  }
} else if (esConsultaEstado) {
  proximoPaso    = 'CONSULTA_ESTADO_PEDIDO';
  instruccionPaso = isEnglish
    ? 'IMPORTANT: The client already placed an order and is asking for a STATUS UPDATE — NOT a new quote. ABSOLUTELY DO NOT recommend any product or crate type. Acknowledge their follow-up, tell them that to check the order status they need to contact the team directly via email or phone. Be empathetic and apologize for any confusion in previous messages.'
    : 'IMPORTANTE: El cliente YA realizó un pedido y quiere saber el ESTADO — NO es una cotización nueva. PROHIBIDO recomendar cajones cerrados ni ningún producto. Reconoce su seguimiento, dile que para consultar el estado de su pedido debe contactar al equipo directamente por correo o teléfono. Sé empático y discúlpate si hubo confusión en mensajes anteriores.';
} else if (!datosRecolectados.tipo_flujo) {
  proximoPaso    = 'IDENTIFICAR_NECESIDAD';
  instruccionPaso = isEnglish
    ? 'Check HISTORIAL and the CURRENT message. If the client already said they want a quote or have a question, proceed accordingly without asking again. If still unclear, ask.'
    : 'Revisa el HISTORIAL y el MENSAJE ACTUAL. Si el cliente ya indicó que quiere cotización o tiene una consulta, procede sin preguntar de nuevo. Si aún no está claro, pregunta.';
} else if (cambioDeIntent) {
  proximoPaso    = 'IDENTIFICAR_NECESIDAD';
  instruccionPaso = isEnglish
    ? `The client just changed what they want mid-conversation — the previous intent was "${datosRecolectados.tipo_flujo}" but this new message clearly signals "${intentActualEnMensaje}". Set datos_actualizados.tipo_flujo to "${intentActualEnMensaje}" and respond accordingly — if it's now a consultation, answer their question directly instead of asking for product/measurements; if it's now a quote request, proceed with the quoting flow.`
    : `El cliente acaba de cambiar lo que quiere a mitad de conversación — antes indicó "${datosRecolectados.tipo_flujo}" pero este mensaje nuevo indica claramente "${intentActualEnMensaje}". Actualiza datos_actualizados.tipo_flujo a "${intentActualEnMensaje}" y responde en consecuencia — si ahora es una consulta, responde su pregunta directamente en vez de pedir producto/medidas; si ahora quiere cotizar, sigue el flujo de cotización normal.`;
} else if (esConsulta || escaladaPendiente) {
  proximoPaso    = 'FLUJO_CONSULTA';
  instruccionPaso = isEnglish
    ? 'Answer the consultation. If you cannot answer, ask for their email to escalate.'
    : 'Responde la consulta. Si no puedes responder, pide el correo para escalar.';
} else if (!tieneProducto) {
  proximoPaso    = 'PEDIR_PRODUCTO';
  instruccionPaso = isEnglish
    ? 'Check HISTORIAL. If the client already mentioned what they need to crate, extract it into datos_actualizados.producto and confirm it. Do NOT ask if already mentioned.'
    : 'Revisa el HISTORIAL. Si el cliente ya mencionó qué artículo necesita embalar, extráelo en datos_actualizados.producto y confírmalo. NO preguntes si ya lo dijeron.';
} else if (!tieneMedidas) {
  proximoPaso    = 'PEDIR_MEDIDAS';
  instruccionPaso = isEnglish
    ? 'Ask for measurements (Length × Width × Height in inches).'
    : 'Pide las medidas (Largo × Ancho × Alto en pulgadas).';
} else if (!tieneTipoCajon) {
  proximoPaso    = 'PEDIR_TIPO_CAJON';
  instruccionPaso = isEnglish
    ? 'Check HISTORIAL and the current message first. If the client already stated a crate type preference (closed crate, cage/open, pallet, crib, container platform, trade show packaging, bulk/wholesale), extract it into datos_actualizados.tipo_cajon and confirm it — do NOT override it with your own recommendation. Only if they have not stated a preference, recommend one based on the product and ask if it works for them.'
    : 'Revisa el HISTORIAL y el mensaje actual primero. Si el cliente ya indicó su preferencia de tipo de embalaje (cajón cerrado, jaula/abierta, paleta, cuna, plataforma contenedor, embalaje para feria, al por mayor), extráela en datos_actualizados.tipo_cajon y confírmala — NO le impongas tu propia recomendación. Solo si no ha indicado preferencia, recomienda uno según el producto y pregunta si le parece bien.';
} else if (!tieneProteccion) {
  proximoPaso    = 'PEDIR_PROTECCION';
  instruccionPaso = isEnglish
    ? 'Ask if they need interior protection (foam, bubble wrap). It has additional cost.'
    : 'Pregunta si necesita protección interior (foam, burbuja). Tiene costo adicional.';
} else if (!tieneCorreo) {
  proximoPaso    = 'PEDIR_CORREO';
  instruccionPaso = isEnglish ? 'Ask for their email for the quote.' : 'Pide su correo para enviar la cotización.';
} else if (!tieneFecha) {
  proximoPaso    = 'PEDIR_FECHA';
  instruccionPaso = isEnglish ? 'Ask when they need the crating done.' : 'Pregunta para cuándo necesita el embalaje.';
} else if (!cotizacionEnviada) {
  proximoPaso    = 'LISTO_PARA_COTIZAR';
  instruccionPaso = isEnglish ? 'Tell the client you are calculating the price.' : 'Indica al cliente que vas a calcular el precio.';
} else {
  proximoPaso    = 'POST_COTIZACION';
  instruccionPaso = isEnglish ? 'Follow up after quote. Offer formal quote via email.' : 'Da seguimiento post-cotización. Ofrece cotización formal por correo.';
}

const todosRecolectados = !cotizacionEnviada
  && esCotizacion
  && tieneProducto && tieneMedidas && tieneCorreo
  && tieneTipoCajon && tieneProteccion && tieneFecha;

// Dimensiones
let dimensiones = null;
if (datosRecolectados.medidas) {
  const nums = datosRecolectados.medidas.match(/(\d+(?:\.\d+)?)/g);
  if (nums && nums.length >= 3) {
    dimensiones = { largo: parseFloat(nums[0]), ancho: parseFloat(nums[1]), alto: parseFloat(nums[2]) };
  }
}

// Sistema IA
const sistemaIA = (waConfig.Prompt_Sistema || `Eres Marco, asistente de ventas de Crating Express. Responde SIEMPRE en JSON con: {"respuesta":"...","nombre":null,"producto":null,"medidas":null,"tipo_cajon":null,"proteccion_extra":null,"correo":null,"fecha":null,"cantidad":null,"intento":null,"escalada":false}`)
  .replace('{{CATALOGO}}', catalogoProductos ? `- ${catalogoProductos}` : '')
  .replace('{{INSTRUCCIONES}}', waConfig.Instrucciones_IA || '');

const usuarioIA = `CLIENTE: ${datosRecolectados.nombre_cliente || '(desconocido)'}
DATOS YA RECOLECTADOS (no pedir de nuevo):
- Producto: ${datosRecolectados.producto || '—'}
- Medidas: ${datosRecolectados.medidas || '—'}
- Correo: ${datosRecolectados.correo_contacto || '—'}
- Tipo cajón: ${datosRecolectados.tipo_cajon || '—'}
- Protección extra: ${datosRecolectados.proteccion_extra ?? '—'}
- Fecha: ${datosRecolectados.fecha || '—'}
${historial ? '\nHISTORIAL RECIENTE:\n' + historial : ''}
${kbContexto ? '\nKB RELEVANTE:\n' + kbContexto : ''}

MENSAJE ACTUAL DEL CLIENTE: "${texto}"

PASO SUGERIDO POR EL SISTEMA (puede estar desactualizado si el cliente acaba de cambiar de intención en su MENSAJE ACTUAL): ${proximoPaso}
INSTRUCCIÓN DEL PASO: ${instruccionPaso}
IMPORTANTE: si el MENSAJE ACTUAL contradice esta instrucción (ej. el paso dice pedir un dato pero el cliente recién dijo que solo quiere información, o al revés), priorizá SIEMPRE lo que el cliente dice AHORA por sobre el paso sugerido — respondé acorde a su mensaje real, no al paso fijo.`;

return [{json: {
  telefono: msgData.telefono,
  texto,
  nombreContacto: msgData.nombreContacto,
  leadId,
  leadFields: {},
  estado,
  historial,
  esNuevo,
  emailVendedor,
  followup24,
  followup72,
  datosRecolectados,
  cotizacionEnviada,
  escaladaEnviada,
  idiomaConversacion,
  escaladaPendiente,
  proximoPaso,
  todosRecolectados,
  dimensiones,
  tipoCajaApi: datosRecolectados.tipo_cajon || null,
  saludoHora,
  sistemaIA,
  usuarioIA,
  catalogoFinal: catalogoProductos,
  productosRaw: inp.productos || []
}}];
